{"cards": [{"node_code": "N_e2942dd6770c295c", "definition": "研究面向制造场景的工业数据采集、清洗、特征工程及基于机器学习/深度学习的预测模型，旨在实现故障诊断、寿命预测及质量趋势分析。", "boundary": "聚焦于数据层面的“感知与预测”能力，强调从原始工业数据中提取价值并输出预测结果。边界在于关注数据模型、算法在制造数据上的应用及预测精度，不涉及基于预测结果的实时闭环控制（归入自适应控制）或生产资源调度（归入智能排产）。", "includes": ["基于时序数据的设备故障预测与健康管理（PHM）", "制造过程质量缺陷的机器学习检测与趋势预测", "工业大数据的特征提取、异常检测及数据驱动的状态评估模型"], "excludes": ["不涉及具体工业数据场景的通用统计学或纯数学算法理论", "基于预测结果直接调整机床参数或生产计划的闭环控制策略"], "sibling_distinctions": [{"other_code": "N_b6984b485a31c124", "rule": "本节点关注“预测”（输出状态/趋势/风险）；兄弟节点关注“决策与控制”（基于目标优化排产或实时调整工艺参数）。"}, {"other_code": "N_4682abb12ee67f2b", "rule": "本节点关注算法模型本身及其在数据上的表现；兄弟节点关注承载算法的计算架构（边缘/云）及系统级的自主生产组织形式。"}], "cross_boundary_rule": "若研究核心是构建预测模型并验证其在制造数据上的准确性，主挂载本节点；若研究核心是利用预测结果进行实时参数调整或资源调度，主挂载“智能排产、工艺优化与自适应控制”；若研究核心是部署架构或系统协同，主挂载“边缘智能、云制造与自主生产”。"}, {"node_code": "N_b6984b485a31c124", "definition": "研究利用智能算法实现生产计划动态调度、工艺参数实时优化及制造过程自适应控制的方法，以实现效率、质量与成本的最优平衡。", "boundary": "聚焦于制造过程中的“决策与执行优化”，包括基于约束的排产算法、基于反馈的工艺参数自整定及闭环自适应控制。边界在于强调算法对生产资源或物理过程的直接优化作用，不涉及底层数据预测模型构建（归入工业数据分析）或系统级架构设计（归入边缘/云制造）。", "includes": ["基于强化学习或启发式算法的动态生产排程与调度", "切削/加工参数的实时自适应优化与闭环控制策略", "多目标优化下的工艺路径规划及制造资源动态配置算法"], "excludes": ["不涉及具体制造约束或物理过程的通用组合优化算法", "纯机械结构强度分析或传统开环数控编程"], "sibling_distinctions": [{"other_code": "N_e2942dd6770c295c", "rule": "本节点关注“优化与控制”（改变状态/资源分配）；兄弟节点关注“预测”（评估状态/趋势）。"}, {"other_code": "N_4682abb12ee67f2b", "rule": "本节点关注具体的优化算法与控制逻辑；兄弟节点关注支撑这些算法运行的边缘/云计算架构及分布式自主生产系统。"}], "cross_boundary_rule": "若研究侧重排产算法、参数优化模型或控制律设计，主挂载本节点；若侧重预测模型构建，主挂载“工业数据分析与预测”；若侧重算法在边缘/云端的部署架构或系统协同机制，主挂载“边缘智能、云制造与自主生产”。"}, {"node_code": "N_4682abb12ee67f2b", "definition": "研究边缘计算、云计算在制造系统中的应用架构，以及基于分布式智能实现生产单元自主协同、资源动态共享与系统级自主运行的技术体系。", "boundary": "聚焦于制造系统的“架构与组织形式”，包括边缘-云协同计算、分布式智能体通信、云制造服务平台及具备自主决策能力的生产单元网络。边界在于关注系统层面的计算架构、通信协议及自主协同机制，不涉及具体的预测算法或排产优化模型细节（归入相应算法节点）。", "includes": ["制造场景下的边缘计算架构、端云协同数据处理机制", "云制造服务平台、制造即服务（MaaS）及分布式资源调度架构", "基于多智能体或分布式控制的自主生产单元协同与系统级自主运行"], "excludes": ["不涉及制造系统架构的通用云计算或边缘计算理论", "单一设备内部的局部控制算法或纯数据预测模型"], "sibling_distinctions": [{"other_code": "N_e2942dd6770c295c", "rule": "本节点关注“系统架构与部署”；兄弟节点关注“数据模型与预测算法”。"}, {"other_code": "N_b6984b485a31c124", "rule": "本节点关注“分布式协同与系统自主性”；兄弟节点关注“局部或全局的优化算法与控制策略”。"}], "cross_boundary_rule": "若研究侧重计算架构、端云协同机制或分布式系统组织，主挂载本节点；若侧重具体的预测或优化算法模型，主挂载“工业数据分析与预测”或“智能排产、工艺优化与自适应控制”。"}]}
